-- 148_replace_decision_177_2024_licensing_and_continuation_controls_non_bank_finance_single_article_with_preamble_seven_articles_and_annex.sql
--
-- إعادة هيكلة قرار مجلس إدارة الهيئة العامة للرقابة المالية رقم (177) لسنة 2024 بتاريخ 2024/8/28 بشأن ضوابط منح الترخيص
-- واستمراره للشركات العاملة فى الأنشطة المالية غير المصرفية (منشور بالوقائع المصرية العدد 189 تابع (ب) فى 29 أغسطس 2024).
--
-- ===== الحالة السابقة (مراجعة الـ153 وثيقة، أولوية P2 - المجموعة أ) =====
-- مخزَّن بالهجرة 042 كمادة واحدة (article_no = 1، 13669 حرفاً) تحوى القرار كله (سبع مواد وتوقيع وملحق نسب المساهمة)، بلا
-- ديباجة مستقلة ولا مواد ولا صف article_versions. والمتن نفسه سليم (طبقة نصية حقيقية) لكنه ملوَّث بترويسات صفحات الوقائع ("الوقائع
-- المصریة – العدد 189 تابع )ب( فى 29 أغسطس سنة 2024") وأرقام الصفحات (4-12) داخل المتن بأرقام هندية، وبقايا تنوين منفصل ("وفق ًـا" و
-- "وف ًقا")، وجداول التعريفات والملحق مفككة الأعمدة (اسم النشاط منفصل عن نسبة المساهمة)، وسطر "SPECIAL PURPOSE" مقطوع عن
-- "ACQUISITION COMPANY «SPAC»". فيمتنع الاستشهاد بمادة بعينها ويضعف الاسترجاع (مثلاً شرط نسبة 25% للمؤسسة المالية أو ثلثى رأس المال
-- للمستثمر المؤهل، ومدد التأسيس والترخيص).
--
-- ===== المصدر والمنهجية =====
-- PDF الوقائع المصرية (10 صفحات، قُدِّم من صاحب المشروع). قوبل المتن المخزَّن بطبقة النص المستخرجة (تطبيع NFKC وإزالة علامات الاتجاه
-- والأرقام الهندية) كلمة بكلمة فتطابقا تماماً (2308 كلمة)، ثم قُرئت الصفحات 3–10 بصرياً (130 dpi) للتأكد من الأرقام الجوهرية
-- والجداول: القوانين 159/1981 و95/1992 و93/2000 و148/2001 و80/2002 و10/2009 و141/2014 و176/2018 و18/2020 و5/2022 و155/2024،
-- القرارات 11/2014 و53/2018 و161/2024، جلسة 2024/8/28، المساهم الرئيسى 10% فأكثر، المستثمر المؤهل (عشر سنوات خبرة وخمسة ملايين جنيه،
-- عشرة ملايين، خمسون مليوناً)، مساهمة المؤسسة المالية 25% أو ثلثا رأس المال للمستثمر المؤهل، تمثيل المرأة 25%، ستة أشهر للتأسيس،
-- ثلاثة أشهر للترخيص، ستة أشهر لبدء النشاط، أسبوعان للموافقة الضمنية، وجدول الملحق (4 تصنيفات دولية: BBB وBBB وBaa وB+).
-- حُذفت ترويسات الصفحات وأرقامها، وفُكَّت علامات التنوين المنفصلة ("وفقاً" "مرفقاً" "مملوكاً" "لاغياً"). أُبقى إملاء المصدر وهفواته
-- كما وردت بالصورة: الياء غير المنقوطة "ى" فى "فى" و"المصرفى" و"يلى"، "غير المصرية" بدل "غير المصرفية" فى البند 12 من المادة 4، "الرئيسين"
-- فى (ب)، "ما لم رد إليه اعتباره" بلا "يرد"، ونقطة شاردة بعد "على" فى البند 8 ("على . الأقل بخلاف العضو المنتدب"). الأرقام لاتينية. أُسقطت علامات
-- التشكيل الصغيرة وأُبقى تنوين الفتح. جداول التعريفات وملحق النسب كُتبت صفاً صفاً بصيغة "النشاط : النسبة" (على غرار القرار 101/2020،
-- الهجرة 143). التوقيع داخل المادة السابعة. عنوان القرار فى hierarchical_location للديباجة، وعنوان كل مادة فى عنوانها.
--
-- ===== الهيكل =====
-- 9 صفوف، 9 نسخ (version_no = 1): ديباجة (article_no = 0) بأربعة عشر اطلاعاً وجلسة المجلس (ولا تنتهى بنقطتين بعد "قرر" فى المصدر)، المواد 1–7
-- (نطاق السريان، تعريفات [شركة عاملة، مساهم رئيسى، مؤسسات مالية 22 بنداً، مستثمر مؤهل، شركة ذات غرض استحواذ SPAC]، ضوابط عامة، ضوابط
-- الموافقة المبدئية والترخيص [12 بنداً وشروط الشخص الاعتبارى]، شروط استمرار الترخيص، الإلغاء [القرار 53/2018]، النشر والتوقيع)،
-- والمادة 8 = ملحق (1) نسب مساهمة المؤسسة المالية أو المستثمرين المؤهلين لكل نشاط (الأوراق المالية والتأمين والتمويل العقارى والاستهلاكى).
-- المفتاح (1، 0) محفوظ حتى لا تعيد بذرة 042 إدراج المادة القديمة (إدراج laws فيها ON CONFLICT DO NOTHING فلا تُدرج مواد لقانون موجود).
--
-- ===== التاريخ =====
-- effective_from = 2024-08-30 (اليوم التالى لنشر الوقائع فى 29/8/2024، وفق المادة 7: "ويعمل بهذا القرار من اليوم التالى لتاريخ نشره بالوقائع
-- المصرية"). لا تُمس بيانات laws، ولا يُعدَّل سجل القرار 53/2018 (المادة 6 تلغيه؛ حالته in_force فى قاعدتنا اليوم وتُعالج فى هجرة حالات لاحقة بعد التحقق).
--
-- ===== قابلية إعادة التشغيل =====
-- الحذف مشروط بألا تكون الحالة نظيفة (9 صفوف بديباجة سليمة والمادة 8 موجودة)؛ والإدراج ON CONFLICT DO NOTHING. تحقق الختام محصور فى هذا
-- القرار ويفشل عند أى انحراف (عدد، تلف، بقايا ترويسة أو تنوين منفصل، محتوى المواد والملحق، إجمالى الطول 11699 حرفاً).
--
-- ملاحظة تشغيلية: المواد الجديدة بلا embedding؛ يلزم scripts/backfill-embeddings.js بعد النشر.

BEGIN;
DO $fix148$
DECLARE
  v_law_id uuid;
  v_n int;
BEGIN
  SELECT id INTO v_law_id FROM laws WHERE law_no = 177 AND law_year = 2024 AND kind = 'board_decision';
  IF v_law_id IS NULL THEN
    RAISE WARNING '[148] القرار 177/2024 غير موجود فى laws — تخطّى';
    RETURN;
  END IF;
  IF (SELECT count(*) FROM articles WHERE law_id = v_law_id) = 9
     AND EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 0 AND article_suffix_order = 0 AND title = 'ديباجة القرار' AND body LIKE 'بعد الاطلاع%')
     AND EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 8 AND article_suffix_order = 0) THEN
    RAISE NOTICE '[148] القرار 177/2024 نظيف بالفعل — تخطّى الحذف';
  ELSE
    SELECT count(*) INTO v_n FROM articles WHERE law_id = v_law_id;
    DELETE FROM articles WHERE law_id = v_law_id;
    RAISE NOTICE '[148] أُزيلت % مادة من القرار 177/2024 (القرار كله فى مادة واحدة بترويسات صفحات وأرقام وتنوين منفصل وجداول مفككة)', v_n;
  END IF;
END
$fix148$;

WITH ins0_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 0, 0, $h0$قرار مجلس إدارة الهيئة العامة للرقابة المالية رقم 177 لسنة 2024 بتاريخ 2024/8/28 (منشور بالوقائع المصرية العدد 189 تابع (ب) فى 2024/8/29) بشأن ضوابط منح الترخيص واستمراره للشركات العاملة فى الأنشطة المالية غير المصرفية$h0$, $t0_0$ديباجة القرار$t0_0$, $b0_0$بعد الاطلاع على قانون شركات المساهمة وشركات التوصية بالأسهم والشركات ذات المسئولية المحدودة وشركات الشخص الواحد الصادر بالقانون رقم 159 لسنة 1981 ولائحته التنفيذية ؛
وعلى قانون سوق رأس المال الصادر بالقانون رقم 95 لسنة 1992 ولائحته التنفيذية ؛
وعلى قانون الإيداع والقيد المركزى للأوراق والأدوات المالية الصادر بالقانون رقم 93 لسنة 2000 ولائحته التنفيذية ؛
وعلى قانون التمويل العقارى الصادر بالقانون رقم 148 لسنة 2001 ولائحته التنفيذية ؛
وعلى قانون مكافحة غسل الأموال الصادر بالقانون رقم 80 لسنة 2002 ولائحته التنفيذية ؛
وعلى القانون رقم 10 لسنة 2009 بتنظيم الرقابة على الأسواق والأدوات المالية غير المصرفية ؛
وعلى القانون رقم 141 لسنة 2014 بتنظيم مزاولة نشاط تمويل المشروعات المتوسطة والصغيرة ومتناهية الصغر ؛
وعلى قانون تنظيم نشاطى التأجير التمويلى والتخصيم الصادر بالقانون رقم 176 لسنة 2018 ؛
وعلى قانون تنظيم نشاط التمويل الاستهلاكى الصادر بالقانون رقم 18 لسنة 2020 ؛
وعلى قانون تنظيم وتنمية استخدام التكنولوجيا المالية فى الأنشطة المالية غير المصرفية الصادر بالقانون رقم 5 لسنة 2022 ؛
وعلى قانون التأمين الموحد الصادر بالقانون رقم 155 لسنة 2024 ؛
وعلى قرار مجلس إدارة الهيئة رقم 11 لسنة 2014 بشأن قواعد قيد وشطب الأوراق المالية بالبورصة المصرية ؛
وعلى قرار مجلس إدارة الهيئة رقم 53 لسنة 2018 بشأن ضوابط منح الترخيص واستمراره وقواعد تملك أسهم الشركات العاملة فى مجال الأنشطة المالية غير المصرفية ؛
وعلى قرار مجلس إدارة الهيئة رقم 161 لسنة 2024 بشأن الضوابط الرقابية فى مجال غسل الأموال وتمويل الإرهاب للجهات العاملة فى مجال الأنشطة المالية غير المصرفية ؛
وبعد موافقة مجلس إدارة الهيئة بجلسته المنعقدة بتاريخ 2024/8/28 ؛
قرر$b0_0$
  FROM laws WHERE law_no = 177 AND law_year = 2024 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2024-08-30', 'active' FROM ins0_0;

WITH ins1_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 1, 0, NULL, $t1_0$المادة الأولى - نطاق السريان$t1_0$, $b1_0$تسرى أحكام هذا القرار بشأن ضوابط منح الترخيص واستمراره للشركات العاملة فى مجال الأنشطة المالية غير المصرفية .$b1_0$
  FROM laws WHERE law_no = 177 AND law_year = 2024 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2024-08-30', 'active' FROM ins1_0;

WITH ins2_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 2, 0, NULL, $t2_0$المادة الثانية - تعريفات$t2_0$, $b2_0$فى تطبيق أحكام هذا القرار ، يقصد بالكلمات والعبارات التالية المعنى المبين قرين كل منها :
الشركة العاملة فى الأنشطة المالية غير المصرفية : هى الشركة المرخص لها من الهيئة بمزاولة أى من الأنشطة المالية غير المصرفية ، ويشار إليها فى أحكام هذا القرار ب «الشركة العاملة» .
المساهم الرئيسي : المساهم المالك لنسبة 10% فأكثر من رأس مال الشركة سواء بمفرده أو من خلال أطرافه المرتبطة .
المؤسسات المالية :
1- البنوك المصرية وفروع البنوك الأجنبية الخاضعة لإشراف البنك المركزى المصرى .
2- شركات التأمين أو إعادة التأمين .
3- الشركات التى يكون غرضها الاشتراك فى تأسيس الشركات التى تصدر أوراق مالية أو زيادة رؤوس أموالها .
4- الشركات والجهات التى تزاول نشاط البورصات .
5- شركات الوساطة فى السندات والمتعاملون الرئيسيون .
6- شركات رأس المال المخاطر .
7- شركات المقاصة والإيداع والقيد المركزى .
8- شركات التمويل العقارى أو إعادة التمويل العقارى .
9- شركات التأجير التمويلى أو التخصيم .
10- شركات التمويل الاستهلاكى .
11- شركات تمويل المشروعات المتوسطة والصغيرة و/أو متناهية الصغر .
12- صناديق الاستثمار .
13- شركات الاستثمار المباشر .
14- الهيئة القومية للبريد .
15- بنك ناصر الاجتماعى .
16- صناديق التأمين الخاصة التى تبلغ حجم أموالها المستثمرة أكثر من 100 مليون جنيه .
17- جهاز تنمية المشروعات المتوسطة والصغيرة ومتناهية الصغر .
18- صندوق مصر السيادى للاستثمار والتنمية .
19- صندوق مصر الفرعى للخدمات المالية والتحول الرقمى .
20- الشركات أو الجهات من الأشخاص الاعتبارية العامة والخاصة الصادر بشأنها قرار من مجلس إدارة الهيئة .
21- الأشخاص الاعتبارية الأجنبية التى تمارس إحدى الأنشطة المالية المصرفية أو غير المصرفية الخاضعة لإشراف ورقابة جهة تمارس اختصاصات مثيلة للبنك المركزى المصرى أو الهيئة بحسب الأحوال .
22- المؤسسات المالية العربية والإقليمية والدولية التى توافق عليها الهيئة .
المستثمر المؤهل : يقصد بالمستثمر المؤهل أى مما يلى :
( أ ) الأشخاص الطبيعيون من ذوى الخبرة التى لا تقل عن عشر سنوات فى مجال إدارة الأموال واستثمارها و/أو الاستثمار المباشر و/أو المجالات المرتبطة بالأنشطة المالية المصرفية أو غير المصرفية ، على ألا تقل قيمة الأصول السائلة أو الأوراق أو الأدوات المالية المملوكة له عن خمسة ملايين جنيه .
(ب) الجهات الحكومية والأشخاص الاعتبارية العامة وأجهزة الدولة التى تسمح القوانين والقرارات المنظمة لها بمزاولة أنشطة مالية واستثمارية بما فيها تأسيس الشركات أو المساهمة فيها .
(ج) شركات الأموال التى لا تقل حقوق الملكية بها عن عشرة ملايين جنيه .
(د) الشركات الأجنبية التى لا تقل حقوق الملكية بها عن خمسين مليون جنيه أو ما يعادلها بالعملات الأجنبية .
(ه) المؤسسات المالية المشار إليها بهذا القرار .
الشركة ذات غرض الاستحواذ (SPECIAL PURPOSE ACQUISITION COMPANY «SPAC») : هى إحدى الشركات التى يتم تأسيسها والترخيص لها كشركة رأس مال مخاطر ، وتكون ذات غرض وحيد هو الاستحواذ على شركات أخرى ، وتقوم بالحصول على التمويل اللازم للقيام بعمليات الاستحواذ من خلال طرح زيادة رأس مالها فى اكتتاب خاص .$b2_0$
  FROM laws WHERE law_no = 177 AND law_year = 2024 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2024-08-30', 'active' FROM ins2_0;

WITH ins3_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 3, 0, NULL, $t3_0$المادة الثالثة - ضوابط عامة$t3_0$, $b3_0$تكون الموافقة على طلبات تأسيس أو ترخيص الشركات العاملة فى ضوء حاجة السوق للنشاط المطلوب الترخيص به أو تأسيس شركة لمباشرته بناءً على دراسة للسوق تعتمد من مجلس إدارة الهيئة ، أو تقديم منتجات جديدة أو تطوير منتجات قائمة –بحسب الأحوال ، – وبمراعاة توافر الاشتراطات الأخرى الواجب الالتزام بها وفقاً للتشريعات المنظمة لكل نشاط ، وبمراعاة أثار التركز الاقتصادى على المنافسة فى السوق .
وبالنسبة للشركات ذات غرض الاستحواذ فتلتزم بتقديم طلب قيد أسهمها بالبورصة خلال شهر من تاريخ حصولها على الترخيص وإلا اعتبر ترخيصها كأن لم يكن ، وفى حال شطب قيد أسهم الشركة من البورصة يتم إلغاء ترخيصها وتلتزم باتخاذ إجراءات التصفية ، وذلك ما لم تقدم الشركة مبررات تقبلها الهيئة.$b3_0$
  FROM laws WHERE law_no = 177 AND law_year = 2024 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2024-08-30', 'active' FROM ins3_0;

WITH ins4_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 4, 0, NULL, $t4_0$المادة الرابعة - ضوابط إصدار الموافقة المبدئية على التأسيس ، والحصول على الترخيص$t4_0$, $b4_0$مع عدم الإخلال بمتطلبات التأسيس أو الترخيص المطلوبة وفقاً للتشريعات المنظمة لكل نشاط ، يجب على الشركات الراغبة فى الحصول على موافقة مبدئية على التأسيس أو الحصول على ترخيص بمزاولة أحد الأنشطة المالية غير المصرفية ، الالتزام بما يلى :
1- تقديم دراسة الجدوى الفنية والاقتصادية للشركة وفقاً للنموذج المعتمد من الهيئة .
2- ألا تقل نسبة مساهمة المؤسسة المالية عن (25%) من رأس مال الشركة ، أو ألا تقل نسبة المساهمة المباشرة أو غير المباشرة للمستثمر المؤهل عن ثلثى رأس مال الشركة ، مع الالتزام بالضوابط الخاصة بهيكل الملكية لبعض الأنشطة المالية غير المصرفية على النحو الوارد بالجدول رقم (1) المرفق بهذا القرار .
ويجوز للهيئة أن تطلب أى بيانات أو مستندات للتأكد من المتطلبات الواجب توافرها فى المستثمر المؤهل .
3- الإفصاح عن المستفيد النهائى للمساهمين وفقاً للأحكام الواردة بالباب الثالث عشر من اللائحة التنفيذية لقانون سوق رأس المال .
4- تقديم إقرار بالالتزام بالقرارات الصادرة عن الهيئة المنظمة لمزاولة الأنشطة المالية غير المصرفية .
5- وجوب استخدام أسلوب التصويت التراكمى فى انتخاب أعضاء مجلس الإدارة بما يسمح بالتمثيل النسبى فى عضوية مجلس الإدارة كلما أمكن ذلك .
6- ألا يقل نسبة تمثيل المرأة فى مجلس إدارة الشركة عن (25%) .
7- الانتهاء من إجراءات التأسيس خلال فترة لا تزيد على ستة أشهر من تاريخ موافقة الهيئة المبدئية ، ويجوز للهيئة مدها لمدد أخرى بناءً على مبررات تقبلها الهيئة وبمراعاة التشريعات المنظمة لبعض الأنشطة ، وفى حالة عدم إنهاء تأسيس الشركة فى المدد المحددة تعتبر موافقة الهيئة المبدئية كأن لم تكن .
8- استيفاء كافة متطلبات الحصول على الترخيص خلال ثلاثة أشهر على الأكثر من تاريخ القيد بالسجل التجارى ، ويجوز مدها بناءً على مبررات تقبلها الهيئة ، وفى حالة تجاوز الشركة المدد المحددة للتقدم بمستندات الترخيص يجوز للهيئة فى ضوء حاجة السوق قبول الطلب بعد تحديث مستندات الشركة بما فيها تحديث دراسة الجدوى الفنية والاقتصادية أو تقديم دراسة جديدة واستيفاء كافة متطلبات الترخيص بمزاولة النشاط وفقاً للضوابط المعمول بها وقت تقديم طلب الترخيص ، على أن يكون من بينها توافر خبرة فى القطاع المالى المصرفى و/أو غير المصرفى لدى نصف أعضاء مجلس إدارة الشركة على . الأقل بخلاف العضو المنتدب وذلك وفقاً لمدد الخبرة المنصوص عليها بقرارات مجلس إدارة الهيئة الصادرة فى شأن كل نشاط ، ومع الالتزام بأن يكون ربع أعضاء مجلس إدارة شركات التأمين على الأقل من ذوى الخبرة فى مجال التأمين . ولا تسرى متطلبات الخبرة الواردة بهذا البند فى شأن الشركات التى تقدم استشارات مهنية .
9- أن يتم بدء العمل فى النشاط والانتهاء من التجهيزات المطلوبة وتعيين فريق العمل بالخبرات المطلوبة وفقاً لكل نشاط والبدء الفعلى للنشاط خلال ستة أشهر على الأكثر من تاريخ الحصول على الترخيص ، ويجوز مد هذه المدة فى ضوء المبررات التى تقدمها الشركة وتقبلها الهيئة ، وفى حالة عدم البدء الفعلى للنشاط فى المدد المحددة يعتبر الترخيص لاغياً .
10- استيفاء نموذج الإفصاح المعد من الهيئة فى شأن التحقق من مصادر أموال مؤسسى الشركة ومساهميها الرئيسيين .
11- ألا يكون أى من مؤسسى الشركة أو مساهميها الرئيسيين أو المستفيدين النهائيين أو أعضاء مجلس الإدارة مدرجين فى القوائم السلبية المتعلقة بالعقوبات المحلية أو الدولية .
12- ألا يكون أى من أعضاء مجلس إدارة الشركة قد صدر ضده خلال الخمس سنوات السابقة على العضوية أى أحكام نهائية بعقوبة جناية ، أو بعقوبة جنحة فى جريمة ماسة بالشرف أو الأمانة أو إحدى الجرائم المنصوص عليها فى القوانين المنظمة للأنشطة المالية غير المصرية ما لم يكن قد رد إليه اعتباره أو فقد شرط حسن السمعة وفقاً للضوابط القانونية المقررة ، أو تكرر اتهام أياً منهم بارتكاب مخالفات جسيمة للقوانين المنظمة لنشاطه خلال آخر ثلاث سنوات ما لم يقض ببراءته .
ويشترط أن يتوافر فى الشخص الاعتبارى الذى يجوز له المشاركة فى تأسيس الشركات العاملة ما يلى :
( أ ) ألا يكون فى حالة إعسار مالى أو إفلاس .
( ب ) ألا تكون الهيئة قد اتخذت ضده أو أى من مساهميه الرئيسين أو أعضاء مجلس إدارته إجراءات تحريك الدعوى الجنائية بشأن أحد الجرائم المنصوص عليها فى القوانين والقواعد المنظمة للأنشطة المالية غير المصرفية أو صدرت ضد أى منهم أحكام قضائية نهائية فى أى من تلك الجرائم أو الجرائم المنصوص عليها بقانون البنك المركزى والجهاز المصرفى أو قانون مكافحة غسل الأموال خلال الثلاث سنوات السابقة على طلب التأسيس ما لم يكن قد تصالح عنها ، أو يكون قد صدر ضد أى منهم أحكام نهائية بعقوبة جنائية أو جنحة فى جريمة مخلة بالشرف أو الأمانة ما لم رد إليه اعتباره .
(ج) ألا تكون الجهة الإدارية التابع لها قد اتخذت ضده أى من التدابير الاحترازية أو الجزاءات الإدارية –باستثناء التنبيه والإنذار – خلال السنوات الثلاث السابقة على طلب التأسيس ما لم تكن قد أزيلت أسبابها ومرت ستة أشهر على تلك الإزالة .
كما تسرى الأحكام الواردة بالبنود السابقة على المستثمرين المؤهلين المشاركين فى تأسيس الشركة العاملة .$b4_0$
  FROM laws WHERE law_no = 177 AND law_year = 2024 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
