WITH ins8_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 8, 0, $h8$ملحق (1) بقرار مجلس إدارة الهيئة رقم 177 لسنة 2024 (الجدول رقم 1 المشار إليه بالمادة الرابعة)$h8$, $t8_0$ملحق (1) - نسبة مساهمة المؤسسة المالية أو المستثمرين المؤهلين لكل نشاط$t8_0$, $b8_0$الشركات العاملة فى مجال الأوراق المالية
1- تقييم وتصنيف وترتيب الأوراق المالية : لا يشترط توافر مؤسسة مالية أو مستثمر مؤهل .
2- الاستشارات المالية عن الأوراق المالية : لا يشترط توافر مؤسسة مالية أو مستثمر مؤهل .
الشركات العاملة فى مجال التأمين
1- شركات التأمين (أشخاص / ممتلكات) وشركات إعادة التأمين : يشترط أن تكون نسبة المساهمة المملوكة للمؤسسات المالية بها لا تقل عن (25%) من رأس المال ، على ألا تقل حقوق الملكية بها عن خمسة مليار جنيه وأن تكون مصنفة من قبل أحد جهات التصنيف الدولية التالية وبما لا يقل عن التصنيف قرين كل جهة : Standard & Poors (BBB) ، Fitch (BBB) ، Moody’s (Baa) ، A.M Best (B+) .
2- شركات الوساطة فى التأمين / إعادة التأمين : يشترط توافر مؤسسات مالية بنسبة لا تقل عن (25%) .
3- شركات التأمين متناهى الصغر : يشترط توافر مؤسسات مالية بنسبة لا تقل عن (25%) .
4- شركات التأمين الطبى المتخصص : يشترط توافر مؤسسات مالية بنسبة لا تقل عن (25%) .
5- شركات خبراء تقييم الأخطار ومعاينة وتقدير الأضرار : لا يشترط توافر مؤسسة مالية أو مستثمر مؤهل .
6- شركات خبراء التأمين الاستشاريون : لا يشترط توافر مؤسسة مالية أو مستثمر مؤهل .
7- شركات الخبرة الاكتوارية : لا يشترط توافر مؤسسة مالية أو مستثمر مؤهل .
8- شركات إدارة برامج التأمين الطبى : لا يشترط توافر مؤسسة مالية أو مستثمر مؤهل .
الشركات العاملة فى مجال التمويل العقارى
1- شركات إعادة التمويل العقارى : الالتزام بحكم البند (ب) من المادة (30) من اللائحة التنفيذية لقانون التمويل العقارى .
2- شركات خبرة التقييم العقارى : لا يشترط توافر مؤسسة مالية أو مستثمر مؤهل .
3- شركات وساطة التمويل العقارى : لا يشترط توافر مؤسسة مالية أو مستثمر مؤهل .
الشركات العاملة فى مجال التمويل الاستهلاكى
شركات التمويل الاستهلاكي : الالتزام بحكم البند (3) من المادة (9) من قانون تنظيم نشاط التمويل الاستهلاكى .$b8_0$
