DO $verify148$
DECLARE
  v_law_id uuid;
  v_n int; v_v int; v_bad int; v_len int;
BEGIN
  SELECT id INTO v_law_id FROM laws WHERE law_no = 177 AND law_year = 2024 AND kind = 'board_decision';
  IF v_law_id IS NULL THEN
    RAISE WARNING '[148] القرار 177/2024 غير موجود — لا تحقق';
    RETURN;
  END IF;
  SELECT count(*), COALESCE(sum(length(body)), 0) INTO v_n, v_len FROM articles WHERE law_id = v_law_id;
  IF v_n <> 9 THEN RAISE EXCEPTION '[148] عدد المواد % بدل 9', v_n; END IF;
  SELECT count(*) INTO v_v FROM article_versions av JOIN articles a ON a.id = av.article_id WHERE a.law_id = v_law_id AND av.version_no = 1 AND av.status = 'active' AND av.effective_from = DATE '2024-08-30';
  IF v_v <> 9 THEN RAISE EXCEPTION '[148] عدد النسخ % بدل 9', v_v; END IF;
  SELECT count(*) INTO v_bad FROM articles WHERE law_id = v_law_id AND (body ~ '[٠-٩۰-۹]' OR body ~ '[ٌ-ْ]' OR body LIKE '%' || chr(65533) || '%' OR body LIKE '%ـ%' OR body LIKE '%العدد 189%' OR body LIKE '%تابع )%' OR body LIKE '%أغسطس سنة%' OR body LIKE '%المصریة%' OR body LIKE '% ً%' OR body LIKE '%ـ%' OR body LIKE '%٢٠٢٤%' OR body LIKE '%SPECIAL PURPOSE
%' OR body LIKE '%ملحق )%');
  IF v_bad > 0 THEN RAISE EXCEPTION '[148] % مادة بها تلف أو بقايا OCR أو ترويسة', v_bad; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 0 AND article_suffix_order = 0 AND body LIKE 'بعد الاطلاع%' AND body LIKE '%رقم 159 لسنة 1981%' AND body LIKE '%رقم 95 لسنة 1992%' AND body LIKE '%رقم 93 لسنة 2000%' AND body LIKE '%رقم 148 لسنة 2001%' AND body LIKE '%رقم 80 لسنة 2002%' AND body LIKE '%رقم 10 لسنة 2009%' AND body LIKE '%رقم 141 لسنة 2014%' AND body LIKE '%رقم 176 لسنة 2018%' AND body LIKE '%رقم 18 لسنة 2020%' AND body LIKE '%رقم 5 لسنة 2022%' AND body LIKE '%رقم 155 لسنة 2024%' AND body LIKE '%رقم 11 لسنة 2014%' AND body LIKE '%رقم 53 لسنة 2018%' AND body LIKE '%رقم 161 لسنة 2024%' AND body LIKE '%بتاريخ 2024/8/28 ؛%' AND body LIKE '%؛
قرر') THEN RAISE EXCEPTION '[148] الديباجة غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 1 AND article_suffix_order = 0 AND body LIKE 'تسرى أحكام هذا القرار%' AND body LIKE '%للشركات العاملة فى مجال الأنشطة المالية غير المصرفية .') THEN RAISE EXCEPTION '[148] المادة 1 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 2 AND article_suffix_order = 0 AND body LIKE 'فى تطبيق أحكام هذا القرار%' AND body LIKE '%المساهم الرئيسي : المساهم المالك لنسبة 10% فأكثر%' AND body LIKE '%1- البنوك المصرية وفروع البنوك الأجنبية%' AND body LIKE '%15- بنك ناصر الاجتماعى .%' AND body LIKE '%16- صناديق التأمين الخاصة%أكثر من 100 مليون جنيه .%' AND body LIKE '%19- صندوق مصر الفرعى للخدمات المالية والتحول الرقمى .%' AND body LIKE '%22- المؤسسات المالية العربية والإقليمية والدولية%توافق عليها الهيئة .%' AND body LIKE '%عن عشر سنوات فى مجال إدارة الأموال%خمسة ملايين جنيه .%' AND body LIKE '%(د) الشركات الأجنبية%عن خمسين مليون جنيه%' AND body LIKE '%(ه) المؤسسات المالية المشار إليها بهذا القرار .%' AND body LIKE '%(SPECIAL PURPOSE ACQUISITION COMPANY «SPAC») : هى إحدى الشركات%فى اكتتاب خاص .') THEN RAISE EXCEPTION '[148] المادة 2 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 3 AND article_suffix_order = 0 AND body LIKE 'تكون الموافقة على طلبات تأسيس%' AND body LIKE '%وبالنسبة للشركات ذات غرض الاستحواذ%خلال شهر من تاريخ حصولها على الترخيص%' AND body LIKE '%مبررات تقبلها الهيئة.') THEN RAISE EXCEPTION '[148] المادة 3 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 4 AND article_suffix_order = 0 AND body LIKE 'مع عدم الإخلال بمتطلبات التأسيس%' AND body LIKE '%عن (25%) من رأس مال الشركة%ثلثى رأس مال الشركة%بالجدول رقم (1) المرفق بهذا القرار .%' AND body LIKE '%6- ألا يقل نسبة تمثيل المرأة%(25%) .%' AND body LIKE '%7- الانتهاء من إجراءات التأسيس خلال فترة لا تزيد على ستة أشهر%' AND body LIKE '%8- استيفاء كافة متطلبات الحصول على الترخيص خلال ثلاثة أشهر%' AND body LIKE '%نصف أعضاء مجلس إدارة الشركة على . الأقل بخلاف العضو المنتدب%' AND body LIKE '%ربع أعضاء مجلس إدارة شركات التأمين%' AND body LIKE '%9- أن يتم بدء العمل فى النشاط%خلال ستة أشهر على الأكثر%لاغياً .%' AND body LIKE '%12- ألا يكون أى من أعضاء مجلس إدارة الشركة%الخمس سنوات السابقة%ما لم يقض ببراءته .%' AND body LIKE '%(ج) ألا تكون الجهة الإدارية التابع لها%ستة أشهر على تلك الإزالة .%' AND body LIKE '%كما تسرى الأحكام الواردة بالبنود السابقة%تأسيس الشركة العاملة .') THEN RAISE EXCEPTION '[148] المادة 4 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 5 AND article_suffix_order = 0 AND body LIKE 'تعد القرارات الصادرة عن الهيئة%' AND body LIKE '%مضى أسبوعين دون رد من الهيئة بمثابة موافقة على إجراء هذا التعديل .') THEN RAISE EXCEPTION '[148] المادة 5 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 6 AND article_suffix_order = 0 AND body LIKE 'يلغى قرار مجلس إدارة الهيئة رقم 53 لسنة 2018 المشار إليه%' AND body LIKE '%أحكام هذا القرار .') THEN RAISE EXCEPTION '[148] المادة 6 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 7 AND article_suffix_order = 0 AND body LIKE 'ينشر هذا القرار فى الوقائع المصرية%' AND body LIKE '%الموقع الإلكترونى للهيئة والبورصة المصرية%' AND body LIKE '%من اليوم التالى لتاريخ نشره بالوقائع المصرية .%' AND body LIKE '%د/ محمد فريد صالح') THEN RAISE EXCEPTION '[148] المادة 7 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 8 AND article_suffix_order = 0 AND body LIKE 'الشركات العاملة فى مجال الأوراق المالية%' AND body LIKE '%1- تقييم وتصنيف وترتيب الأوراق المالية : لا يشترط توافر مؤسسة مالية أو مستثمر مؤهل .%' AND body LIKE '%خمسة مليار جنيه%Standard & Poors (BBB)%Fitch (BBB)%(Baa)%(B+) .%' AND body LIKE '%2- شركات الوساطة فى التأمين / إعادة التأمين : يشترط توافر مؤسسات مالية بنسبة لا تقل عن (25%) .%' AND body LIKE '%8- شركات إدارة برامج التأمين الطبى : لا يشترط%' AND body LIKE '%البند (ب) من المادة (30) من اللائحة التنفيذية لقانون التمويل العقارى .%' AND body LIKE '%البند (3) من المادة (9) من قانون تنظيم نشاط التمويل الاستهلاكى .') THEN RAISE EXCEPTION '[148] الملحق غير سليم'; END IF;
  IF v_len <> 11699 THEN RAISE EXCEPTION '[148] إجمالى طول المواد % بدل 11699', v_len; END IF;
  RAISE NOTICE '[148] القرار 177/2024: 9 مواد و9 نسخ، إجمالى % حرف', v_len;
END
$verify148$;

COMMIT;
